import * as C from '../../../../i18n/constants.mjs';
import { registerCondition } from '../../conditionRegisterer.mjs';
import { parseToLocalDate } from '../../../../helpers/dateTime.mjs';
export const CONDITION_NAME = 'intl_date_today';
/**
 * @param dataRow The object which holds and describes the single cell value.
 * @returns Whether the cell value is today's date.
 */ export function condition(dataRow) {
    const dataDate = parseToLocalDate(dataRow.value);
    if (dataDate === null) {
        return false;
    }
    const now = new Date();
    return dataDate.getFullYear() === now.getFullYear() && dataDate.getMonth() === now.getMonth() && dataDate.getDate() === now.getDate();
}
registerCondition(CONDITION_NAME, condition, {
    name: C.FILTERS_CONDITIONS_TODAY,
    inputsCount: 0,
    inputType: 'date'
});
